"""Intent tests for risk.summary_stats (M1-T19, RISK-04, TC-07)."""

from __future__ import annotations

import pytest

from risk import Returns, TickerSummary, VolSeries, summary_stats


def as_returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def as_vol(payload: dict) -> VolSeries:
    return VolSeries(
        returns=as_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def by_ticker(summaries: tuple[TickerSummary, ...]) -> dict[str, TickerSummary]:
    return {s.ticker: s for s in summaries}


@pytest.mark.intent
def test_tc07_one_summary_per_ticker_in_ticker_order(golden):
    payload, expected = golden("risk", "TC-07")

    summaries = summary_stats(as_vol(payload["vol"]))

    assert [s.ticker for s in summaries] == [row["ticker"] for row in expected["summary"]]
    assert all(isinstance(s, TickerSummary) for s in summaries)


@pytest.mark.intent
@pytest.mark.parametrize("field", ["ann_return", "ann_vol", "sharpe"])
def test_tc07_annualized_stats_match_within_tolerance(golden, field):
    payload, expected = golden("risk", "TC-07")
    tol = expected["tol"]

    got = by_ticker(summary_stats(as_vol(payload["vol"])))

    for row in expected["summary"]:
        assert getattr(got[row["ticker"]], field) == pytest.approx(row[field], abs=tol, rel=0)


@pytest.mark.intent
def test_tc07_zero_volatility_ticker_has_zero_sharpe(golden):
    payload, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    flat = next(row for row in expected["summary"] if row["ann_vol"] == 0)

    got = by_ticker(summary_stats(as_vol(payload["vol"])))[flat["ticker"]]

    assert got.ann_vol == pytest.approx(0.0, abs=tol, rel=0)
    assert got.sharpe == pytest.approx(flat["sharpe"], abs=tol, rel=0)


@pytest.mark.intent
def test_tc07_reports_the_last_rolling_vol(golden):
    payload, expected = golden("risk", "TC-07")
    tol = expected["tol"]

    got = by_ticker(summary_stats(as_vol(payload["vol"])))

    for row in expected["summary"]:
        last_vol = got[row["ticker"]].last_vol
        assert last_vol is not None
        assert last_vol == pytest.approx(row["last_vol"], abs=tol, rel=0)


@pytest.mark.intent
def test_tc07_default_is_252_periods_per_year(golden):
    payload, _ = golden("risk", "TC-07")
    vol = as_vol(payload["vol"])

    assert summary_stats(vol) == summary_stats(vol, periods_per_year=252)


@pytest.mark.intent
def test_fewer_than_two_returns_raises_value_error(contract_sample):
    sample = contract_sample("risk.VolSeries")
    one = {
        "returns": {
            "base_date": sample["returns"]["base_date"],
            "dates": sample["returns"]["dates"][:1],
            "tickers": sample["returns"]["tickers"],
            "values": {t: v[:1] for t, v in sample["returns"]["values"].items()},
        },
        "window": sample["window"],
        "annualized": sample["annualized"],
        "values": {t: v[:1] for t, v in sample["values"].items()},
    }

    with pytest.raises(ValueError, match=r"(?i)two|2"):
        summary_stats(as_vol(one))

